insert into public.diagnostico_items
  (id, area, tipo, peso, elo, elo_base, enunciado, opciones, fen, correcta, solucion, alternas, explica, lichess, rating)
values
  ('cal_conteo', 'calculo', 'opcion', 2, 1270, 950, 'Una casilla está defendida dos veces y atacada dos veces por ti. ¿Qué hay que contar antes de capturar ahí?', '["El valor de las piezas que entran, en orden.","Solo cuántos atacantes hay: si son dos, se gana.","Si el rey rival está cerca de esa casilla o no.","Nada en especial: capturar siempre conviene."]'::jsonb, null, 0, null, null, 'Capturar de a poco y en orden equivocado regala material. Cuenta la secuencia completa antes de la primera captura.', null, null),
  ('cal_jaque_doble', 'calculo', 'casilla', 1, 850, 950, 'Haz clic en la casilla desde la que tu caballo daría jaque al rey negro y atacaría la torre a la vez.', null, '3k4/6r1/8/8/3N4/8/8/7K w - - 0 1', null, '"e6"'::jsonb, null, 'Antes de mover un caballo, mira sus 8 saltos: el tenedor casi siempre está en uno que no miraste.', null, null),
  ('cal_intermedia', 'calculo', 'opcion', 2, 1330, 1200, '¿Qué es una jugada intermedia (zwischenzug)?', '["Meter un jaque o una amenaza antes de recapturar.","Una jugada de peón a mitad de la partida.","La jugada número 20, cuando acaba la apertura.","Repetir la posición dos veces para hacer tablas."]'::jsonb, null, 0, null, null, 'Al calcular, pregúntate siempre: "¿puedo meter un jaque útil antes de recapturar?". Ahí aparecen medio punto y muchas piezas.', null, null),
  ('cal_torre_bloqueo', 'calculo', 'opcion', 1, 610, 700, '¿Puede una torre saltar por encima de otras piezas?', '["No: se detiene en la primera pieza del camino.","Sí, siempre y por encima de cualquier pieza.","Sí, pero solo por encima de los peones.","Solo en su primera jugada de la partida."]'::jsonb, null, 0, null, null, 'Salvo el caballo, ninguna pieza salta por encima de otra: la torre se detiene en la primera pieza que encuentra en su línea de movimiento.', null, null),
  ('cal_orden_capturas', 'calculo', 'opcion', 1, 990, 950, 'Al calcular una serie de capturas en una misma casilla, ¿qué principio general conviene seguir?', '["Capturar primero con la pieza de menor valor.","Capturar siempre primero con la dama, que manda.","No capturar nunca con peones en esa casilla.","Capturar siempre con la pieza más valiosa."]'::jsonb, null, 0, null, null, 'La regla práctica es "capturar de menor a mayor valor": si la secuencia de cambios se corta a mitad de camino, no arriesgaste tu pieza más valiosa de entrada.', null, null),
  ('cal_jaques_primero', 'calculo', 'opcion', 2, 1280, 1200, 'En el cálculo de variantes forzadas (jaques, capturas, amenazas), ¿por qué conviene analizar primero los jaques?', '["Porque limitan mucho las respuestas del rival.","Porque un jaque casi siempre gana la partida.","Porque no se puede capturar estando en jaque.","Porque el jaque solo obliga en los finales."]'::jsonb, null, 0, null, null, 'Los jaques son la jugada más forzada posible: reducen mucho las respuestas legales del rival, lo que hace más fácil calcular esa rama con precisión.', null, null),
  ('tac_doble_ataque', 'tactica', 'opcion', 1, 610, 700, '¿Cómo se llama la jugada que ataca dos piezas rivales al mismo tiempo?', '["Ataque doble, u tenedor si es de caballo.","Clavada, que deja inmóvil a una pieza.","Enroque largo por el flanco de dama.","Jugada de espera, para ganar un tiempo entero."]'::jsonb, null, 0, null, null, 'El ataque doble gana material porque el rival alcanza a salvar una sola de las dos piezas. Es la táctica más común de todas: vale la pena buscarla en cada jugada.', null, null),
  ('tac_descubierta', 'tactica', 'opcion', 2, 1210, 700, 'Mueves una pieza y, al quitarse de en medio, la que estaba detrás ataca algo importante. ¿Cómo se llama eso?', '["Ataque a la descubierta: atacan dos piezas.","Clavada, porque la pieza de atrás queda fija.","Captura al paso con el peón que pasa.","Ahogado del rey que no puede mover."]'::jsonb, null, 0, null, null, 'En la descubierta la pieza que se mueve queda libre para hacer cualquier cosa (incluso ponerse donde la pueden capturar), porque el rival tiene que atender el ataque de la pieza de atrás.', null, null),
  ('tac_colgada', 'tactica', 'opcion', 1, 700, 700, 'En el ajedrez de club se dice que una pieza está "colgada". ¿Qué quiere decir?', '["Que está sin defensa: nadie la recaptura.","Que está en la última fila del tablero.","Que no se ha movido en toda la partida.","Que está clavada contra su propio rey."]'::jsonb, null, 0, null, null, 'Antes de cada jugada conviene revisar las piezas colgadas —las tuyas y las del rival—: la mitad de las tácticas de una partida de club salen de ahí.', null, null),
  ('tac_clavada_tablero', 'tactica', 'jugada', 1, 530, 700, 'Clava el caballo negro contra su rey: juega la jugada de alfil tras la cual ese caballo no se puede mover.', null, '4k3/8/2n5/8/8/8/8/4KB2 w - - 0 1', null, '{"from":"f1","to":"b5"}'::jsonb, null, 'Con el alfil en b5 el caballo de c6 queda entre el alfil y su propio rey: moverlo sería dejar al rey en jaque, así que no puede. Una pieza clavada contra el rey no defiende nada.', null, null),
  ('tac_enfilada', 'tactica', 'opcion', 2, 1300, 950, '¿Qué es una enfilada (en inglés, skewer)?', '["Como una clavada al revés: la valiosa está adelante.","Dos peones propios que se defienden en la misma diagonal.","Un jaque que se repite tres veces y hace tablas.","Una torre que llega a la séptima y come peones."]'::jsonb, null, 0, null, null, 'Clavada y enfilada son la misma línea de ataque, cambiando el orden: en la clavada la pieza valiosa está atrás; en la enfilada, adelante, y se gana lo que queda detrás.', null, null),
  ('tac_enfilada_tablero', 'tactica', 'jugada', 1, 820, 950, 'Gana la dama negra con una enfilada: da jaque de manera que, al moverse el rey, la torre se coma la dama.', null, '8/8/8/2k4q/8/8/8/R5K1 w - - 0 1', null, '{"from":"a1","to":"a5"}'::jsonb, null, 'Con Ta5+ el rey y la dama quedan en la misma fila: el rey tapa la única casilla por donde la dama podría interponerse, así que tiene que salirse de la fila 5 y ahí cae la dama.', null, null),
  ('tac_jaque_doble', 'tactica', 'opcion', 1, 850, 950, 'El rey recibe jaque de dos piezas a la vez (jaque doble). ¿Qué puede hacer el rival?', '["Solo mover el rey: no hay forma de tapar los dos.","Capturar una de las dos piezas que dan jaque.","Interponer una pieza en las dos líneas a la vez.","Nada: el jaque doble siempre termina en mate."]'::jsonb, null, 0, null, null, 'Por eso el jaque doble es tan fuerte: como el rey está obligado a moverse, la pieza que lo da puede quedar atacada sin que importe.', null, null),
  ('tac_doble_jaque_tablero', 'tactica', 'jugada', 1, 790, 1200, 'Da jaque doble: mueve el caballo de modo que el rey negro quede en jaque del caballo y de la torre al mismo tiempo.', null, '2k5/8/8/8/2N5/8/8/2R3K1 w - - 0 1', null, '{"from":"c4","to":"b6"}'::jsonb, '[{"from":"c4","to":"d6"}]'::jsonb, 'El caballo se corre de la columna c (con lo que la torre da jaque) y desde b6 o d6 ataca él mismo al rey. Dos jaques a la vez: el rey no tiene más remedio que moverse.', null, null),
  ('tac_atraccion', 'tactica', 'opcion', 1, 870, 950, '¿En qué consiste la táctica de atracción (o señuelo)?', '["Sacrificar algo para atraer una pieza a una casilla mala.","Retirar las piezas propias a la primera fila y esperar.","Cambiar todas las piezas para llegar rápido al final.","Mover el mismo caballo varias veces para ganar tiempo."]'::jsonb, null, 0, null, null, 'Atracción y desviación son primas: una arrastra a la pieza adonde te conviene, la otra la saca de donde estorbaba. En las dos, el sacrificio se paga con la táctica que viene después.', null, null),
  ('tac_pieza_atrapada', 'tactica', 'opcion', 1, 880, 950, 'Tu rival metió la dama a comer un peón lejos de sus piezas. ¿Qué idea vale la pena buscar?', '["Atraparla: quitarle una por una las casillas de salida.","Cambiar damas cuanto antes, antes de que ella vuelva.","Dar jaques hasta que regrese sola a su campo.","Avanzar todos los peones del flanco de rey."]'::jsonb, null, 0, null, null, 'Una pieza atrapada es material ganado aunque la captura llegue tres jugadas después: primero se le cierran las salidas y al final se cobra.', null, null),
  ('tac_perpetuo', 'tactica', 'opcion', 1, 1080, 950, 'Vas perdiendo por una pieza, pero puedes dar jaque una y otra vez sin que el rey rival se escape. ¿Qué resultado buscas?', '["Tablas por jaque perpetuo.","Ganar por tiempo en el reloj.","Mate en tres jugadas.","Que el rival quede ahogado."]'::jsonb, null, 0, null, null, 'El jaque perpetuo es el salvavidas de las posiciones perdidas: si el rey rival no puede salir de la red de jaques, la partida termina en tablas por repetición.', null, null),
  ('tac_sobrecarga', 'tactica', 'opcion', 2, 1320, 1200, 'Una torre rival es la única que defiende dos cosas a la vez. ¿Cómo se llama esa debilidad y cómo se aprovecha?', '["Sobrecarga: se ataca una cosa y suelta la otra.","Clavada: la torre no se puede mover de esa casilla.","Zugzwang: la torre está obligada a mover.","Enfilada: la torre cae por estar en línea."]'::jsonb, null, 0, null, null, 'La pregunta que la descubre es siempre la misma: "¿qué defiende esta pieza?". Si la respuesta son dos cosas, hay táctica.', null, null),
  ('tac_interferencia', 'tactica', 'opcion', 3, 1580, 1200, '¿Qué es una interferencia (obstrucción)?', '["Cortar con una pieza la línea por la que el rival defiende.","Poner dos peones en la misma columna, uno delante del otro.","Bloquear un peón pasado poniendo el caballo delante.","Cambiar la dama por las dos torres del rival."]'::jsonb, null, 0, null, null, 'La defensa no siempre se puede mover ni desviar: a veces basta con cortarle la línea. Por eso la interferencia suele venir con un sacrificio en la casilla justa.', null, null),
  ('tac_despeje', 'tactica', 'opcion', 2, 1180, 1200, 'Tu propia pieza está tapando la línea por la que tu dama daría mate. ¿Cuál es la idea?', '["Despejar la línea: mover esa pieza con amenaza.","Cambiarla por la pieza rival que tenga más cerca.","Retirarla a la primera fila y volver a empezar.","Dejarla ahí: nunca conviene abrir líneas propias."]'::jsonb, null, 0, null, null, 'El despeje de línea (o de casilla) gana tiempo: la pieza que estorba se va haciendo daño, y detrás de ella ya viene la amenaza de verdad.', null, null),
  ('tac_molino', 'tactica', 'opcion', 2, 1330, 1200, '¿Qué es el "molino", una de las tácticas más vistosas del ajedrez?', '["Jaques a la descubierta con torre y alfil, uno tras otro.","Girar el tablero para ver la posición del otro lado.","Mover el caballo en círculo alrededor del rey rival.","Repetir la misma jugada tres veces seguidas, y quedan tablas."]'::jsonb, null, 0, null, null, 'Funciona porque el rival nunca puede hacer nada: entre jaque y jaque descubierto solo alcanza a mover el rey, mientras la torre cobra todo lo que hay en su camino.', null, null),
  ('tac_socavar', 'tactica', 'opcion', 1, 1010, 1200, 'Una pieza rival bien puesta está sostenida por un peón. ¿Qué significa "socavar" esa posición?', '["Atacar o cambiar el peón que la sostiene.","Atacar la pieza con otra de más valor.","Cambiar las damas para llegar al final.","Poner un peón propio justo delante de ella."]'::jsonb, null, 0, null, null, 'Contra una pieza bien plantada casi nunca sirve atacarla de frente: se le quita el piso, que suele ser un peón.', null, null),
  ('tac_desesperada', 'tactica', 'opcion', 1, 1080, 1200, 'Tu alfil está perdido, no hay forma de salvarlo. ¿Qué conviene hacer con él?', '["Venderlo caro: que se lleve algo antes de caer.","Retirarlo a la primera fila y dejarlo ahí.","Dejarlo donde está y jugar con las demás.","Cambiarlo por un peón cualquiera, el que sea."]'::jsonb, null, 0, null, null, 'Una pieza que igual se va a perder no tiene nada que cuidar: que capture lo más caro que alcance, o que se meta donde obligue al rival a gastar una jugada.', null, null),
  ('mate_jaque_no_es_mate', 'mate', 'opcion', 1, 570, 700, 'Le das jaque al rey rival. ¿Qué tres formas tiene de salir del jaque?', '["Mover el rey, capturar a quien da jaque o tapar.","Solo mover el rey: no hay ninguna otra salida.","Enrocar, capturar la pieza o pedir tablas.","Ninguna: el jaque siempre termina en mate."]'::jsonb, null, 0, null, null, 'Mate es justo cuando ninguna de esas tres salidas existe. Repasarlas en orden —mover, capturar, tapar— es la forma de no cantar mate donde no lo hay.', null, null),
  ('mate_escalera_tablero', 'mate', 'jugada', 1, 760, 950, 'Da jaque mate en una jugada con las dos torres.', null, '7k/1R6/R7/8/8/8/8/6K1 w - - 0 1', null, '{"from":"a6","to":"a8"}'::jsonb, null, 'Es el mate de la escalera: una torre le quita la fila 7 al rey y la otra da el jaque en la fila 8. Sin la torre de b7 el rey se escaparía a h7.', null, null),
  ('mate_tecnica_torre', 'mate', 'opcion', 1, 710, 950, 'Te queda rey y torre contra rey solo. ¿Cuál es el plan para dar mate?', '["Empujar al rey al borde con la torre y acercar el propio.","Dar jaques con la torre lo más rápido que se pueda, sin parar.","Dejar la torre en el centro y esperar al rey rival.","Cambiar la torre por el peón rival más avanzado."]'::jsonb, null, 0, null, null, 'La torre sola no da mate: hace falta el rey propio para quitarle las casillas de escape. Sin plan, la partida se va a tablas por las 50 jugadas.', null, null),
  ('mate_ahogado_cuidado', 'mate', 'opcion', 1, 1030, 950, 'Vas ganando con dama de más contra rey solo. ¿Cuál es el descuido más común?', '["Dejarlo sin jaque y sin jugada legal: es ahogado.","Dar tantos jaques que se acaba el tiempo propio.","Coronar otra dama más sin ninguna necesidad.","Acercar demasiado el propio rey al del rival."]'::jsonb, null, 0, null, null, 'Con dama de ventaja, antes de cada jugada hay que preguntarse: "¿le queda alguna jugada legal?". Si no le queda y no está en jaque, la partida se acabó en tablas.', null, null),
  ('mate_arabe', 'mate', 'opcion', 2, 1220, 1200, '¿Qué piezas trabajan juntas en el llamado mate árabe?', '["Torre y caballo, contra el rey en la esquina.","Los dos alfiles, en diagonales que se cruzan.","Dama y peón, con el peón dando apoyo.","Dos peones ligados que llegan juntos."]'::jsonb, null, 0, null, null, 'Torre y caballo se entienden muy bien alrededor del rey enrocado: vale la pena reconocer el patrón, porque aparece en cientos de finales de ataque.', null, null),
  ('mate_anastasia', 'mate', 'opcion', 3, 1480, 1200, 'En el mate de Anastasia, ¿qué hace el caballo?', '["Se planta en e7 y le quita al rey las casillas de g.","Da él mismo el jaque final desde f7, como en la coz.","Se cambia por el alfil que defiende al rey.","Bloquea el peón pasado que corre del otro lado."]'::jsonb, null, 0, null, null, 'Es un patrón de ataque al enroque: caballo en e7, sacrificio de dama en h7 si hace falta y torre a la columna h. Conocerlo hace que la combinación aparezca sola.', null, null),
  ('cal_diagonal', 'calculo', 'opcion', 1, 840, 700, 'Sin mirar el tablero: ¿un alfil que está en e4 puede llegar en una jugada a a8 (si el camino está libre)?', '["Sí: e4, d5, c6, b7 y a8 van en diagonal.","No: e4 y a8 son de colores distintos.","No: un alfil no cruza tantas casillas.","Solo si es el alfil de casillas negras."]'::jsonb, null, 0, null, null, 'Ver las diagonales sin mover las piezas es media batalla del cálculo. El truco: de e4 hacia arriba y a la izquierda, letra que baja y número que sube.', null, null),
  ('cal_candidatas', 'calculo', 'opcion', 1, 1060, 950, 'Antes de calcular a fondo, ¿qué conviene hacer primero?', '["Elegir dos o tres jugadas candidatas y calcularlas.","Calcular hasta el final la primera que se ocurra.","Mirar cuánto tiempo le queda al rival en el reloj.","Cambiar piezas para simplificar la posición."]'::jsonb, null, 0, null, null, 'Sin lista de candidatas se calcula mucho y se elige mal: casi siempre la buena era la que nunca se miró.', null, null),
  ('cal_respuesta_rival', 'calculo', 'opcion', 2, 1280, 950, '¿Cuál es el error más caro al calcular una variante?', '["Darle al rival la respuesta que a uno le conviene.","Calcular sin tocar las piezas del tablero.","Empezar el cálculo por los jaques posibles.","Contar el valor de las piezas antes de entrar en ella."]'::jsonb, null, 0, null, null, 'En cada jugada del rival hay que buscar su mejor defensa, no la que deja lucir la combinación. Si la variante aguanta eso, sirve.', null, null),
  ('cal_posicion_tranquila', 'calculo', 'opcion', 2, 1370, 1200, '¿Hasta dónde hay que calcular una variante de capturas?', '["Hasta una posición tranquila, sin capturas pendientes.","Exactamente tres jugadas, siempre, en cualquier caso.","Hasta que se acabe el tiempo de pensar la jugada.","Hasta la primera captura, y ahí ya se decide."]'::jsonb, null, 0, null, null, 'Cortar el cálculo a mitad de una serie de cambios es la trampa clásica: la posición parecía buena justo antes de la recaptura que lo cambiaba todo.', null, null),
  ('reg_jaque_obligado', 'reglas', 'opcion', 1, 1060, 1200, 'Tu rey está en jaque y tienes una jugada que gana la dama rival, pero no te saca del jaque. ¿Qué puedes hacer?', '["Nada: en jaque solo valen las jugadas que lo resuelven.","Ganar la dama: con material de más se gana igual de fácil.","Cualquiera de las dos, a elección del jugador.","Ganar la dama, si después puedes tapar el jaque."]'::jsonb, null, 0, null, null, 'El jaque es obligatorio de atender: mover el rey, capturar a quien lo da o interponer algo. Cualquier otra jugada, por buena que sea, no existe.', null, null),
  ('mat_cambiar_ganando', 'material', 'opcion', 2, 1270, 1200, 'Vas ganando una pieza. ¿Qué criterio de cambios te conviene?', '["Cambiar piezas, no peones: la ventaja pesa más.","Cambiar peones, no piezas: así se abren líneas.","No cambiar nada: cada cambio le da una chance.","Cambiar damas solo si el rival lo propone."]'::jsonb, null, 0, null, null, 'Es la regla práctica que convierte ventajas en puntos: con pieza de más, cada cambio de piezas acerca el final ganado; los peones, en cambio, hacen falta para coronar.', null, null),
  ('est_rey_final', 'estrategia', 'opcion', 1, 1040, 700, 'En el final, ¿qué pasa con el rey?', '["Se vuelve una pieza fuerte: hay que activarlo.","Sigue escondido en el enroque hasta el final.","Solo sirve para dar el mate, nada más.","Conviene dejarlo atrás para que no lo ataquen."]'::jsonb, null, 0, null, null, 'Con pocas piezas ya no hay quien lo ataque: el rey pasa de ser el que se esconde a ser la pieza que decide, y quien lo activa primero suele ganar el final.', null, null),
  ('reg_enroque_torre_atacada', 'reglas', 'opcion', 3, 1400, 1450, 'Enroque largo: la casilla b1, por la que pasa la torre, está atacada por un alfil negro. Las casillas del rey (e1, d1, c1) están todas libres de ataque. ¿Se puede enrocar?', '["Sí: la regla mira solo las casillas del rey.","No: tampoco puede estar atacada la casilla de la torre.","Sí, si después del enroque el alfil deja de atacar b1.","No, salvo que la torre esté defendida por otra pieza."]'::jsonb, null, 0, null, null, 'El reglamento habla del rey: no puede estar en jaque, ni pasar ni terminar en casilla atacada. La torre puede cruzar b1 atacada sin problema — es la diferencia que más se discute en torneos escolares.', null, null),
  ('reg_repeticion', 'reglas', 'opcion', 4, 1700, 1450, 'Para reclamar tablas por repetición, ¿qué es exactamente lo que tiene que repetirse tres veces?', '["La posición, con el mismo turno y los mismos derechos.","Las mismas tres jugadas de cada bando, en el mismo orden.","La posición, sin importar a quién le toque mover.","El mismo jaque, tres veces seguidas en la partida."]'::jsonb, null, 0, null, null, 'Son posiciones, no jugadas, y tienen que ser idénticas en todo: mismo turno, mismos enroques posibles y misma posibilidad de captura al paso. Por eso a veces "la misma posición" no cuenta.', null, null),
  ('reg_tiempo_sin_material', 'reglas', 'opcion', 3, 1520, 1700, 'A tu rival se le cae la bandera (se le acaba el tiempo). A ti te queda solo el rey. ¿Cuál es el resultado?', '["Tablas: sin material para dar mate no se gana por tiempo.","Ganas tú: quien se queda sin tiempo pierde siempre.","Gana tu rival, porque tiene más material que tú.","Se sigue jugando: la caída de bandera no cuenta en este caso."]'::jsonb, null, 0, null, null, 'Es el artículo del reglamento que más partidas de torneo decide mal cuando no se conoce: sin material para dar mate ni siquiera con la peor defensa posible, la caída de bandera es empate.', null, null),
  ('reg_enroque_toque', 'reglas', 'opcion', 2, 1170, 1700, 'En torneo, con pieza tocada: quieres enrocar y tocas primero la torre. ¿Qué pasa?', '["Solo puedes mover la torre: el enroque se toca del rey.","Igual puedes enrocar: se ve que la intención era esa.","Pierdes el derecho al enroque para toda la partida.","Nada: la regla de pieza tocada no aplica al enroque."]'::jsonb, null, 0, null, null, 'El enroque es una jugada de rey. Tocar la torre primero obliga a jugarla sola, y si estaba mal ubicada se pierde el enroque de esa jugada — un detalle que solo aparece cuando se juega con árbitro.', null, null),
  ('mat_calidad_sacrificio', 'material', 'opcion', 2, 1220, 1450, 'Sacrificar la calidad (dar torre por alfil o caballo). ¿Cuándo suele valer la pena?', '["Cuando a cambio queda algo permanente: casillas o estructura.","Nunca: cinco puntos contra tres siempre es perder material.","Siempre que se recupere al menos un peón en el camino.","Solo en los finales de torres, donde no se aprovecha."]'::jsonb, null, 0, null, null, 'La calidad se entrega por ventajas que no se van: casillas, estructura, seguridad del rey. Si lo que se obtiene se puede deshacer en tres jugadas, el sacrificio no era.', null, null),
  ('mat_dos_menores_vs_torre', 'material', 'opcion', 2, 1380, 1450, 'Dos piezas menores contra torre y peón, con damas y varias piezas todavía en el tablero. ¿Qué prefieres?', '["Las dos menores: con el tablero lleno coordinan mejor.","La torre y el peón: seis puntos contra seis, y es mayor.","Da exactamente lo mismo: el conteo no engaña.","La torre, salvo que una menor sea un alfil malo."]'::jsonb, null, 0, null, null, 'La tabla de valores es una guía de principiante: en el medio juego dos menores activas valen más que torre y peón, y la relación se da vuelta cuando se cambian piezas y se abren columnas.', null, null),
  ('mat_pareja_alfiles_contra', 'material', 'opcion', 3, 1430, 1700, 'Tu rival tiene la pareja de alfiles y tú alfil y caballo. ¿Cuál es el plan correcto?', '["Cerrar la posición y cambiar uno de los dos alfiles.","Abrir la posición para que el caballo tenga casillas.","Cambiar damas: sin damas la pareja ya no cuenta.","Avanzar los peones donde él tiene el alfil bueno."]'::jsonb, null, 0, null, null, 'La pareja vale por el trabajo conjunto en posiciones abiertas. Trabar los peones y cambiar uno de los dos la desarma: es la receta de Steinitz para el lado que no la tiene.', null, null),
  ('mat_dos_torres_vs_dama_fuerte', 'material', 'opcion', 3, 1490, 1700, 'Dos torres contra dama, con peones en los dos flancos. ¿Cuándo pelea mejor la dama?', '["Cuando hay peones sueltos que cobrar y el rey al aire.","Siempre: se mueve mucho más que las dos torres juntas.","Nunca: dos torres coordinadas ganan en toda posición.","Solo si quedan menos de cuatro peones en el tablero."]'::jsonb, null, 0, null, null, 'Es la relación de material que menos se decide por la tabla: dos torres bien puestas y con el rey seguro valen más, pero la dama se come las posiciones con debilidades sueltas y reyes al aire.', null, null),
  ('ap_carlsbad', 'apertura', 'opcion', 4, 1700, 1450, 'Estructura Carlsbad (peones blancos en c3, d4, e3 y negros en c6, d5, e6, con el cambio ya hecho en d5). ¿Cuál es el plan clásico de las blancas?', '["El ataque de minorías: b4-b5 y cambio en c6.","Avanzar e3-e4 ya mismo, aunque quede un aislado.","Enrocar largo y tirar los peones del flanco de rey.","Cambiar todo para llegar a un final de peones."]'::jsonb, null, 0, null, null, 'Dos peones atacando a tres: el cambio en c6 deja un peón atrasado en columna semiabierta. Es el plan más enseñado del Gambito de Dama y se juega igual en 1900 y hoy.', null, null),
  ('ap_peon_aislado', 'apertura', 'opcion', 3, 1620, 1450, 'Juegas contra un peón dama aislado del rival (su peón en d4, sin peones en c ni e). ¿Cuál es la estrategia correcta?', '["Cambiar piezas y bloquear la casilla de adelante.","Cambiar peones y dejar las piezas para atacarlo.","Capturarlo cuanto antes, cueste lo que cueste.","Evitar los cambios y jugar en el flanco de dama."]'::jsonb, null, 0, null, null, 'El peón aislado da actividad en el medio juego y es una debilidad en el final: quien lo sufre cambia piezas y bloquea; quien lo tiene evita los cambios y busca la ruptura d4-d5.', null, null),
  ('ap_orden_jugadas', 'apertura', 'opcion', 2, 1120, 1700, '¿Por qué los jugadores fuertes cuidan tanto el orden de jugadas en la apertura?', '["Porque transponiendo se elige a qué variante entrar.","Porque el reglamento obliga a sacar primero los caballos.","Porque cambiar el orden hace perder el enroque.","Porque así se gana tiempo en el reloj del rival."]'::jsonb, null, 0, null, null, 'La misma posición se llega por caminos distintos, y en el camino cada bando tiene desvíos. Elegir el orden es elegir qué desvíos le dejas al rival.', null, null),
  ('ap_najdorf_a6', 'apertura', 'opcion', 3, 1490, 1700, 'Siciliana Najdorf (1.e4 c5 2.Cf3 d6 3.d4 cxd4 4.Cxd4 Cf6 5.Cc3 a6). ¿Para qué juegan las negras ...a6?', '["Le quita b5 a las blancas y prepara ...e5.","Prepara el enroque largo de las negras.","Ataca el peón de b2 con la torre de a8.","Evita que las blancas jueguen el gambito."]'::jsonb, null, 0, null, null, 'Es una jugada de profilaxis pura: no desarrolla nada, pero le quita una casilla clave al rival y habilita el plan que las negras quieren (...e5 y ...b5).', null, null),
  ('tac_sacrificio_f7', 'tactica', 'jugada', 1, 760, 1450, 'Encuentra el golpe que fuerza el mate en dos. Juega solo ese golpe.', null, '6k1/5ppp/6Q1/5R2/8/8/8/6K1 w - - 0 1', null, '{"from":"g6","to":"f7"}'::jsonb, null, 'Dxf7+ arrastra al rey (o tapa con la torre) y el mate llega en la siguiente. El sacrificio en f7 es el punto flojo del enroque corto desde la primera partida que uno juega.', null, null),
  ('tac_orden_amenazas', 'tactica', 'opcion', 1, 1090, 1450, 'Tu rival amenaza mate en una jugada y tú puedes ganar una torre. ¿Qué manda?', '["Parar el mate, salvo que ganar la torre lo pare también.","Ganar la torre: con material de más se defiende mejor.","Cambiar damas para simplificar la posición y respirar.","Dar jaque con cualquier pieza para ganar un tiempo."]'::jsonb, null, 0, null, null, 'Lo forzado va antes que lo bueno. La excepción vale la pena buscarla siempre: una jugada que gana material Y para el mate es la que hay que encontrar.', null, null)
